/**
 * PMT 图池取数（/files/pmt/maps20xx.json）。
 * 图池按比赛年份组织，曲绘也取那一年的样子（见 illChange.js）。
 */
import { loadJson } from './jsonCache.js'
import { decorateSongMap } from './common.js'
import { loadIllChange } from './illChange.js'

export async function getPmtMaps(jsonPath, ymd) {
  try {
    const [jsonData, illChange] = await Promise.all([loadJson(jsonPath), loadIllChange()])
    return decorateSongMap(jsonData, ['EZ', 'HD', 'IN', 'AT'], illChange, ymd)
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('请求路径：', jsonPath)
    return {}
  }
}
